import { isUndefined } from 'lodash-es';

import { WithId } from '../../../../core/types/with-id.js';
import {
  HistogramAnnotationsMarkerProps,
  isHistogramValueAnnotation,
} from '../../../types/histogram-annotations.js';

const getFrom = (marker: WithId<HistogramAnnotationsMarkerProps>) => {
  return isHistogramValueAnnotation(marker.value)
    ? marker.value
    : marker.value.from;
};

const getTo = (marker: WithId<HistogramAnnotationsMarkerProps>) => {
  return isHistogramValueAnnotation(marker.value)
    ? marker.value
    : marker.value.to;
};

export interface SameValueGroup {
  priority?: number;
  markers: WithId<HistogramAnnotationsMarkerProps>[];
}

/**
 * Given an array of markers returns an array of groups containing those markers that have overlapping values or ranges.
 * Each group contains another array grouping those values that has exactly the same value or range.
 *
 * @param markers - markers to group
 * @param trackPriority - a priority number defined by the markers track. If a marker doesn't have its priority defined, then it has this track's priority assigned. The default is undefined.
 */
export function groupMarkers(
  markers: WithId<HistogramAnnotationsMarkerProps>[],
  trackPriority?: number,
) {
  const groups: SameValueGroup[][] = [];
  const tooltipGroups: WithId<HistogramAnnotationsMarkerProps>[][][] = [];

  const sortedByMin = [...markers].sort(
    (markerA, markerB) =>
      Math.min(getFrom(markerA), getTo(markerA)) -
      Math.min(getFrom(markerB), getTo(markerB)),
  );

  for (let i = 0; i < sortedByMin.length; i++) {
    const current = sortedByMin[i];
    const currentPriority = current.priority ?? trackPriority;
    const currentMin = Math.min(getFrom(current), getTo(current));

    const groupIndex = groups.findIndex((group) =>
      group.some((marker: SameValueGroup) => {
        const valueMax = Math.max(
          getFrom(marker.markers[0]),
          getTo(marker.markers[0]),
        );
        const isValue = isHistogramValueAnnotation(marker.markers[0].value);

        return isValue ? currentMin <= valueMax : currentMin < valueMax;
      }),
    );

    if (groupIndex !== -1) {
      const overlappingGroup = groups[groupIndex];
      const sameValueIndex = overlappingGroup.findIndex((group) =>
        group.markers.some((groupValue) => {
          return (
            getFrom(current) === getFrom(groupValue) &&
            getTo(current) === getTo(groupValue)
          );
        }),
      );

      if (sameValueIndex !== -1) {
        //Cases when markers have same value or range
        const groupPriority = overlappingGroup[sameValueIndex].priority;
        overlappingGroup[sameValueIndex].markers.push(current);
        if (
          isUndefined(groupPriority) ||
          (!isUndefined(currentPriority) && currentPriority > groupPriority)
        ) {
          overlappingGroup[sameValueIndex].priority = currentPriority;
        }
        tooltipGroups[groupIndex][sameValueIndex].push(current);
      } else {
        //Cases for overlapping markers that are not the same range
        const newOverlapGroup = {
          markers: [current],
          priority: currentPriority,
        };
        overlappingGroup.push(newOverlapGroup);
        tooltipGroups[groupIndex].push([current]);
      }
    } else {
      const newGroup = {
        markers: [current],
        priority: currentPriority,
      };
      groups.push([newGroup]);
      tooltipGroups.push([[current]]);
    }
  }
  return { groups, tooltipGroups };
}
